function StepBackup{if(-not $script:Ctx.Paths){throw 'SigningRepository required.'};$p=$script:Ctx.Paths;if(-not(Test-Path -LiteralPath $p.KeystorePath -PathType Leaf)){throw 'Keystore not found.'};if(-not(Test-Path -LiteralPath $p.MetadataPath -PathType Leaf)){throw 'Metadata not found; run Metadata first.'};$dest=Join-Path $p.BackupDir (Get-Date -Format 'yyyyMMdd-HHmmss');EnsureDir $dest;Copy-Item -LiteralPath $p.KeystorePath -Destination $dest;Copy-Item -LiteralPath $p.MetadataPath -Destination $dest;$script:Ctx.BackupPath=$dest;Log "Backup created: $dest" Success}
